{"command": "pwsh -NoProfile -Command "
foreach (\$f in @('C:\Users\UserX\AppData\Local\Comfy-Desktop\ComfyUI-Shared\output\IT14_00001_.png','C:\Users\UserX\AppData\Local\Comfy-Desktop\ComfyUI-Shared\output\IT17_00001_.png')) {
  \$b = [System.IO.File]::ReadAllBytes(\$f)
  \$i = 8
  Write-Output ('=== ' + [System.IO.Path]::GetFileName(\$f))
  while (\$i -lt \$b.Length - 8) {
    \$len = [int]\$b[\$i]*16777216 + [int]\$b[\$i+1]*65536 + [int]\$b[\$i+2]*256 + [int]\$b[\$i+3]
    \$type = [System.Text.Encoding]::ASCII.GetString(\$b, \$i+4, 4)
    if (\$type -eq 'tEXt' -or \$type -eq 'iTXt') {
      \$data = [System.Text.Encoding]::UTF8.GetString(\$b, \$i+8, \$len)
      Write-Output ('--- chunk ' + \$type + ' ---')
      Write-Output \$data
    } elseif (\$type -eq 'IEND') { break }
    \$i += 12 + \$len
  }
}
" 2>&1", "description": "Extract embedded text metadata chunks from both PNGs"}

